import json
from decimal import Decimal, ROUND_HALF_UP

def load(name):
    with open(f'fixtures/{name}') as f:
        return json.load(f)

def exact(line):
    return Decimal(line["unit_price"]) * line["qty"] * (100 - Decimal(line.get("discount_pct", 0))) / 100

def rounded(line):
    val = exact(line)
    return val.quantize(Decimal("0.01"), ROUND_HALF_UP)

for name in ["basic.json", "bulk.json"]:
    for invoice in load(name):
        unrounded_sum = sum((exact(l) for l in invoice["lines"]), Decimal(0))
        rounded_sum = unrounded_sum.quantize(Decimal("0.01"), ROUND_HALF_UP)
        sum_of_rounded = sum((rounded(l) for l in invoice["lines"]), Decimal(0))
        print(f"{invoice['id']}: rounded_sum={rounded_sum}, sum_of_rounded={sum_of_rounded}, match={rounded_sum == sum_of_rounded}")
